// whatever the thumbnail pipeline had written moments earlier. Thumbnails get
// their own statement (UpdateMapThumbnail) and their own endpoint.
func (q *Queries) UpdateMapWithVersion(ctx context.Context, arg UpdateMapWithVersionParams) (Map, error) {
	row := q.db.QueryRowContext(ctx, updateMapWithVersion,
		arg.Title,
		arg.Document,
		arg.NodeCount,
		arg.SizeBytes,
		arg.UpdatedAt,
		arg.Uid,
		arg.OwnerID,
		arg.ExpectedVersion,
	)
	var i Map
	err := row.Scan(
		&i.ID,
		&i.Uid,
		&i.OwnerID,
		&i.Title,
		&i.Document,
		&i.Version,
		&i.ThumbnailUrl,
		&i.NodeCount,
		&i.SizeBytes,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
